Here's a complete TCP/IP server implementation in C:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>
#include <signal.h>

#define PORT 8080
#define MAX_CLIENTS 10
#define BUFFER_SIZE 1024

// Global variable to handle graceful shutdown
int server_socket = -1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nShutting down server...\n");
    if (server_socket != -1) {
        close(server_socket);
    }
    exit(0);
}

// Function to handle client communication
void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE];
    int bytes_received;

    // Send welcome message to client
    char *welcome_msg = "Welcome to TCP Server!\n";
    send(client_socket, welcome_msg, strlen(welcome_msg), 0);

    while (1) {
        // Clear buffer
        memset(buffer, 0, BUFFER_SIZE);

        // Receive data from client
        bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0);

        if (bytes_received <= 0) {
            if (bytes_received == 0) {
                printf("Client disconnected\n");
            } else {
                perror("recv failed");
            }
            break;
        }

        // Null terminate the received string
        buffer[bytes_received] = '\0';

        printf("Received from client: %s", buffer);

        // Check for exit command
        if (strncmp(buffer, "exit", 4) == 0) {
            printf("Client requested to exit\n");
            break;
        }

        // Echo the message back to client
        char response[BUFFER_SIZE];
        snprintf(response, BUFFER_SIZE, "Server echo: %s", buffer);

        if (send(client_socket, response, strlen(response), 0) == -1) {
            perror("send failed");
            break;
        }
    }

    // Close client socket
    close(client_socket);
    printf("Client connection closed\n");
}

int main() {
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_addr_len = sizeof(client_addr);
    int client_socket;
    int opt = 1;

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket == -1) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Set socket options to reuse address
    if (setsockopt(server_socket, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(server_socket);
        exit(EXIT_FAILURE);
    }

    // Configure server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY; // Accept connections from any IP
    server_addr.sin_port = htons(PORT);

    // Bind socket to address
    if (bind(server_socket, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        close(server_socket);
        exit(EXIT_FAILURE);
    }

    // Listen for connections
    if (listen(server_socket, MAX_CLIENTS) < 0) {
        perror("Listen failed");
        close(server_socket);
        exit(EXIT_FAILURE);
    }

    printf("TCP Server started on port %d\n", PORT);
    printf("Waiting for connections...\n");

    // Main server loop
    while (1) {
        // Accept client connection
        client_socket = accept(server_socket, (struct sockaddr*)&client_addr, &client_addr_len);

        if (client_socket < 0) {
            if (errno == EINTR) {
                // Interrupted by signal, continue
                continue;
            }
            perror("Accept failed");
            continue;
        }

        printf("New client connected from %s:%d\n", 
               inet_ntoa(client_addr.sin_addr), 
               ntohs(client_addr.sin_port));

        // Handle client (in this simple version, one client at a time)
        handle_client(client_socket);
    }

    // Close server socket
    close(server_socket);
    return 0;
}
```

