```c
// tcp_client.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define PORT 8080
#define BUFFER_SIZE 1024

int main() {
    int client_socket;
    struct sockaddr_in server_addr;
    char buffer[BUFFER_SIZE];
    char message[BUFFER_SIZE];

    // Create socket
    client_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (client_socket == -1) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Configure server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    server_addr.sin_addr.s_addr = inet_addr("127.0.0.1"); // localhost

    // Connect to server
    if (connect(client_socket, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("Connection failed");
        close(client_socket);
        exit(EXIT_FAILURE);
    }

    printf("Connected to server\n");

    // Receive welcome message
    int bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0);
    if (bytes_received > 0) {
        buffer[bytes_received] = '\0';
        printf("Server: %s", buffer);
    }

    // Communication loop
    while (1) {
        printf("Enter message (or 'exit' to quit): ");
        fgets(message, BUFFER_SIZE, stdin);

        // Send message to server
        if (send(client_socket, message, strlen(message), 0) == -1) {
            perror("Send failed");
            break;
        }

        // Check if user wants to exit
        if (strncmp(message, "exit", 4) == 0) {
            break;
        }

        // Receive response from server
        bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0);
        if (bytes_received <= 0) {
            printf("Server disconnected\n");
            break;
        }

        buffer[bytes_received] = '\0';
        printf("Server response: %s", buffer);
    }

    // Close socket
    close(client_socket);
    printf("Connection closed\n");

    return 0;
}
```

## Compilation and Usage

To compile and run the programs:

```bash
# Compile the server
gcc -o tcp_server tcp_server.c

# Compile the client
gcc -o tcp_client tcp_client.c

# Run the server (in one terminal)
./tcp_server

# Run the client (in another terminal)
./tcp_client
```

## Key Features

1. **Socket Creation**: Creates a TCP socket using `socket(AF_INET, SOCK_STREAM, 0)`
2. **Address Binding**: Binds the socket to a specific port
3. **Listening**: Listens for incoming connections
4. **Connection Handling**: Accepts and handles client connections
5. **Data Exchange**: Receives and sends data to/from clients
6. **Error Handling**: Proper error checking and handling
7. **Graceful Shutdown**: Signal handlers for clean shutdown
8. **Socket Reuse**: Uses `SO_REUSEADDR` to avoid "Address already in use" errors

## Advanced Version (Multi-threaded)

For handling multiple clients simultaneously, here's a multi-threaded version:

```c
// Add these includes at the top
#include <pthread.h>

// Thread function to handle each client
void* client_thread(void* arg) {
    int client_socket = *(int*)arg;
    free(arg); // Free allocated memory

    handle_client(client_socket);

    pthread_exit(NULL);
}

// In the main loop, replace handle_client(client_socket) with:
pthread_t thread_id;
int* new_sock = malloc(sizeof(int));
*new_sock = client_socket;

if (pthread_create(&thread_id, NULL, client_thread, (void*)new_sock) < 0) {
    perror("Thread creation failed");
    free(new_sock);
    close(client_socket);
    continue;
}

// Detach thread so it cleans up automatically
pthread_detach(thread_id);
```

Compile the multi-threaded version with:
```bash
gcc -o tcp_server_mt tcp_server_mt.c -lpthread
```

This implementation provides a solid foundation for TCP/IP network programming in C.

